import type { Metadata } from "next";
import { site } from "@/content/site";

export const titleSeparator = " · ";

// Generated by app/og.jpg/route.tsx. JPEG keeps the photo card small (WhatsApp drops previews over ~300 KB).
const ogImage = {
  url: "/og.jpg",
  width: 1200,
  height: 630,
  type: "image/jpeg",
  alt: `${site.name}${titleSeparator}${site.role}`,
};

export function pageMetadata({ title, description, path }: { title?: string; description?: string; path: string }): Metadata {
  // Tab title is "Projects · Shivam Vyas" (via the layout's template); the home tab is just the name.
  // Share cards always carry the name, plus the role on the home page.
  const shareTitle = title ? `${title}${titleSeparator}${site.name}` : `${site.name}${titleSeparator}${site.role}`;
  const desc = description ?? site.description;
  return {
    ...(title && { title }),
    description: desc,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_IN",
      url: path,
      title: shareTitle,
      description: desc,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: shareTitle,
      description: desc,
      images: [ogImage.url],
    },
  };
}
